import type { BankQuestion } from "@/lib/bank";

/** Computer Awareness (Computer Awareness): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"comp-awareness-1","question":"Which part is called the brain of the computer?","options":["RAM","Hard disk","CPU","Monitor"],"answer":2,"explanation":"The CPU (Central Processing Unit) processes all instructions.","difficulty":"easy"},
  {"id":"comp-awareness-2","question":"1 byte is equal to:","options":["4 bits","8 bits","16 bits","1024 bits"],"answer":1,"explanation":"A byte has 8 bits.","difficulty":"easy"},
  {"id":"comp-awareness-3","question":"Which of the following is an input device?","options":["Monitor","Printer","Keyboard","Speaker"],"answer":2,"explanation":"A keyboard sends data into the computer; the others are output devices.","difficulty":"easy"},
  {"id":"comp-awareness-4","question":"Which type of memory is volatile?","options":["ROM","RAM","Hard disk","Flash drive"],"answer":1,"explanation":"RAM loses its data when power is switched off.","difficulty":"moderate"},
  {"id":"comp-awareness-5","question":"HTTP stands for:","options":["HyperText Transfer Protocol","High Transfer Text Protocol","HyperText Transmission Process","Hyper Transfer Text Program"],"answer":0,"explanation":"HTTP is the HyperText Transfer Protocol used on the web.","difficulty":"moderate"},
  {"id":"comp-awareness-6","question":"Which shortcut copies selected text in most programs?","options":["Ctrl + V","Ctrl + C","Ctrl + X","Ctrl + P"],"answer":1,"explanation":"Ctrl + C copies, Ctrl + X cuts and Ctrl + V pastes.","difficulty":"moderate"},
  {"id":"comp-awareness-7","question":"1 kilobyte (KB) equals:","options":["1000 bits","1024 bytes","1024 bits","8 bytes"],"answer":1,"explanation":"In computing, 1 KB = 2¹⁰ = 1024 bytes.","difficulty":"hard"},
  {"id":"comp-awareness-8","question":"Which of these is an operating system?","options":["MS Word","Linux","Google Chrome","Oracle"],"answer":1,"explanation":"Linux is an operating system; the others are application software.","difficulty":"hard"},
  {"id":"comp-awareness-9","question":"Which memory is the fastest?","options":["Hard disk","RAM","Cache","ROM"],"answer":2,"explanation":"Cache memory sits closest to the CPU and is faster than RAM.","difficulty":"hard"},
  {"id":"comp-awareness-10","question":"The binary equivalent of the decimal number 10 is:","options":["1001","1010","1100","1011"],"answer":1,"explanation":"10 = 8 + 2 = 1×2³ + 0×2² + 1×2¹ + 0×2⁰ = 1010.","difficulty":"very-hard"},
  {"id":"comp-awareness-11","question":"Which protocol is used to send email?","options":["HTTP","FTP","SMTP","POP3"],"answer":2,"explanation":"SMTP (Simple Mail Transfer Protocol) sends mail; POP3 and IMAP retrieve it.","difficulty":"very-hard"},
  {"id":"comp-awareness-12","question":"Which number system uses base 16?","options":["Binary","Octal","Decimal","Hexadecimal"],"answer":3,"explanation":"Hexadecimal uses 16 symbols, 0–9 and A–F.","difficulty":"very-hard"},
  {"id":"comp-awareness-13","question":"The “brain” of the computer is the:","options":["RAM","CPU","Hard disk","Monitor"],"answer":1,"explanation":"The Central Processing Unit executes instructions.","difficulty":"easy","source":"IBPS Clerk · RRB NTPC"},
  {"id":"comp-awareness-14","question":"Which of these is an output device?","options":["Keyboard","Mouse","Printer","Scanner"],"answer":2,"explanation":"A printer outputs; keyboard, mouse and scanner are input devices.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk"},
  {"id":"comp-awareness-15","question":"1 gigabyte (GB) equals:","options":["1,024 KB","1,024 MB","1,024 TB","1,000 bytes"],"answer":1,"explanation":"KB → MB → GB → TB, each 1,024 times the previous.","difficulty":"moderate","source":"IBPS PO · SBI Clerk"},
  {"id":"comp-awareness-16","question":"In MS Excel, the shortcut key to save a workbook is:","options":["Ctrl + P","Ctrl + S","Ctrl + V","Ctrl + N"],"answer":1,"explanation":"Ctrl + S saves; Ctrl + P prints; Ctrl + N opens a new file.","difficulty":"moderate","source":"IBPS Clerk · SBI Clerk"},
  {"id":"comp-awareness-17","question":"Which memory is volatile, losing its contents when power is switched off?","options":["ROM","RAM","Hard disk","Flash drive"],"answer":1,"explanation":"RAM is volatile; ROM and disks keep data without power.","difficulty":"hard","source":"IBPS PO · SSC CHSL"},
  {"id":"comp-awareness-18","question":"The protocol used to send e-mail from a client to a mail server is:","options":["HTTP","FTP","SMTP","POP3"],"answer":2,"explanation":"SMTP sends mail; POP3/IMAP retrieve it.","difficulty":"very-hard","source":"IBPS PO · SBI PO"},
  {"id":"comp-awareness-19","question":"Which of these is NOT an operating system?","options":["Linux","Windows","Oracle Database","macOS"],"answer":2,"explanation":"Oracle Database is a database management system.","difficulty":"hard"},
  {"id":"comp-awareness-20","question":"The hexadecimal number 1F equals which decimal number?","options":["15","31","30","16"],"answer":1,"explanation":"1F = 1 × 16 + 15 = 31.","difficulty":"hard"},
  {"id":"comp-awareness-21","question":"Which layer of the OSI model handles routing of packets between networks?","options":["Data link","Network","Transport","Session"],"answer":1,"explanation":"The network layer (layer 3) routes packets using IP addresses.","difficulty":"very-hard"},
  {"id":"comp-awareness-22","question":"Which order lists memory from fastest to slowest?","options":["Registers, cache, RAM, hard disk","Cache, registers, RAM, hard disk","RAM, cache, registers, hard disk","Registers, RAM, cache, hard disk"],"answer":0,"explanation":"Registers sit inside the CPU, then cache, then main memory, then storage.","difficulty":"very-hard"},
  {"id":"comp-awareness-23","question":"How many of these statements are correct? I. One byte is eight bits. II. A nibble is four bits. III. ROM is volatile memory. IV. Cache memory sits between the CPU and the main memory.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. ROM keeps its contents without power.","difficulty":"very-hard"},
  {"id":"comp-awareness-24","question":"How many of these statements are correct? I. HTTP uses port 80 by default. II. HTTPS uses port 443 by default. III. FTP is the protocol used to send e-mail.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. E-mail is sent with SMTP; FTP transfers files.","difficulty":"very-hard"},
  {"id":"comp-awareness-25","question":"How many of these statements are correct? I. RAM is volatile memory. II. Cache memory is faster than RAM. III. ROM loses its contents when the power is switched off.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. ROM is non-volatile and keeps its contents without power.","difficulty":"very-hard"},
  {"id":"comp-awareness-26","question":"What is the binary number 101101 in decimal?","options":["45","43","47","53"],"answer":0,"explanation":"32 + 0 + 8 + 4 + 0 + 1 = 45.","difficulty":"very-hard"},
  {"id":"comp-awareness-27","question":"Which layer of the OSI model routes packets between networks?","options":["Network layer","Transport layer","Data link layer","Session layer"],"answer":0,"explanation":"The network layer (layer 3) handles logical addressing and routing; IP works here.","difficulty":"very-hard"},
  {"id":"comp-awareness-28","question":"What is the sum of the hexadecimal number 2A and the binary number 1011, written in decimal?","options":["53","51","47","55"],"answer":0,"explanation":"2A = 2 × 16 + 10 = 42 and 1011 = 8 + 2 + 1 = 11, so the sum is 53.","difficulty":"very-hard","source":"IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-29","question":"How many of these statements are correct? I. A compiler translates a whole program at once, while an interpreter translates it line by line. II. Linux is an open-source operating system. III. A firewall is used to block unauthorised access to a network. IV. Standard ASCII uses 16 bits for each character.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Standard ASCII is a 7-bit code (128 characters), stored in 8-bit bytes; Unicode UTF-16 uses 16 bits.","difficulty":"very-hard","source":"IBPS PO · SBI Clerk"},
  {"id":"comp-awareness-30","question":"URL stands for:","options":["Uniform Resource Locator","Universal Reference Link","Unified Resource Link","Universal Resource Language"],"answer":0,"explanation":"A URL (Uniform Resource Locator) is the address of a resource on the web, such as https://example.com/page.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-31","question":"In MS Word, the shortcut key to make selected text bold is:","options":["Ctrl + I","Ctrl + B","Ctrl + U","Ctrl + D"],"answer":1,"explanation":"Ctrl + B is bold, Ctrl + I italic and Ctrl + U underline.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-32","question":"WWW stands for:","options":["World Web Wire","Wide World Web","World Wide Web","World Wide Wire"],"answer":2,"explanation":"The World Wide Web, invented by Tim Berners-Lee in 1989, is the system of linked hypertext documents accessed over the internet.","difficulty":"easy","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-33","question":"Which generation of computers was based on transistors?","options":["First","Second","Third","Fourth"],"answer":1,"explanation":"First generation used vacuum tubes, second transistors, third integrated circuits and fourth microprocessors.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-34","question":"Which of these is a non-volatile storage device?","options":["RAM","Cache memory","Hard disk","CPU registers"],"answer":2,"explanation":"A hard disk keeps data when power is off; RAM, cache and registers are volatile and lose their contents.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-35","question":"The smallest unit of data in a computer is a:","options":["Byte","Nibble","Bit","Word"],"answer":2,"explanation":"A bit (binary digit) is 0 or 1; a nibble is 4 bits and a byte 8 bits.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-36","question":"Which of the following is application software?","options":["Windows 11","Linux","MS Excel","Device driver"],"answer":2,"explanation":"MS Excel is an application used for a specific task (spreadsheets); operating systems and device drivers are system software.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-37","question":"In MS Excel, the cell address B3 refers to:","options":["Row B, column 3","Column B, row 3","The third sheet","Block 3"],"answer":1,"explanation":"Excel addresses cells by column letter followed by row number, so B3 is the cell in column B and row 3.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-38","question":"The device that lets a computer send digital data over a telephone line is a:","options":["Router","Modem","Switch","Repeater"],"answer":1,"explanation":"A modem (modulator–demodulator) converts digital signals to analogue for the telephone line and back again.","difficulty":"moderate","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-39","question":"The octal equivalent of the binary number 110101 is:","options":["53","65","35","71"],"answer":1,"explanation":"Group the bits in threes from the right: 110 101 → 6 5, so 110101₂ = 65₈ (= 53 in decimal).","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-40","question":"Which protocol automatically assigns IP addresses to devices on a network?","options":["DNS","FTP","DHCP","SMTP"],"answer":2,"explanation":"The Dynamic Host Configuration Protocol leases IP addresses to devices; DNS resolves names, FTP transfers files and SMTP sends mail.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-41","question":"An IPv4 address is how many bits long?","options":["16 bits","32 bits","64 bits","128 bits"],"answer":1,"explanation":"IPv4 uses 32-bit addresses written as four octets (e.g. 192.168.1.1); IPv6 uses 128-bit addresses.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-42","question":"Cache memory in a computer is typically built from:","options":["DRAM","SRAM","EEPROM","Magnetic cores"],"answer":1,"explanation":"Cache uses static RAM, which is faster (no refresh needed) but costlier than the dynamic RAM used for main memory.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-43","question":"The hexadecimal equivalent of the decimal number 255 is:","options":["FF","EE","F0","100"],"answer":0,"explanation":"255 = 15 × 16 + 15, and 15 is F in hexadecimal, so 255 = FF₁₆; 100₁₆ would be 256.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-44","question":"Which program translates assembly language into machine code?","options":["Compiler","Interpreter","Assembler","Loader"],"answer":2,"explanation":"An assembler converts mnemonic assembly instructions into machine code; compilers and interpreters work on high-level languages.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-45","question":"The default port number used by FTP for control connections is:","options":["20","21","23","25"],"answer":1,"explanation":"FTP uses port 21 for commands (and 20 for data); Telnet uses 23 and SMTP 25.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-46","question":"In which network topology are all nodes connected to a central hub or switch?","options":["Bus","Ring","Star","Mesh"],"answer":2,"explanation":"In a star topology each device has its own link to a central device, so one cable failure does not bring down the whole network.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-47","question":"The Domain Name System (DNS) is used to:","options":["Encrypt web traffic","Translate domain names into IP addresses","Assign MAC addresses","Compress web pages"],"answer":1,"explanation":"DNS maps human-readable names such as example.com to numeric IP addresses that routers use.","difficulty":"hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-48","question":"How many of these statements about computer generations are correct? I. First-generation computers used vacuum tubes. II. Second-generation computers used integrated circuits. III. Fourth-generation computers use microprocessors. IV. The fifth generation is associated with artificial intelligence.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are correct. II is wrong: second-generation machines used transistors; integrated circuits mark the third generation.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-49","question":"Assertion (A): Cache memory makes the CPU work faster. Reason (R): Cache keeps frequently used data and instructions close to the CPU, so fewer slow accesses to main memory are needed.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Cache hits avoid the long wait for main memory, so the processor spends less time idle; R is the mechanism behind A.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-50","question":"Match the protocol with its default port: 1. SMTP 2. HTTP 3. HTTPS 4. DNS; a. 443 b. 53 c. 80 d. 25","options":["1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-a, 4-b","1-d, 2-a, 3-c, 4-b","1-b, 2-c, 3-a, 4-d"],"answer":0,"explanation":"SMTP uses port 25, HTTP 80, HTTPS 443 and DNS 53.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-51","question":"How many bits are there in 2 KB of data (1 KB = 1024 bytes)?","options":["2,048","8,192","16,384","20,480"],"answer":2,"explanation":"2 KB = 2 × 1024 = 2,048 bytes = 2,048 × 8 = 16,384 bits.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-52","question":"Which of the following is NOT an input device?","options":["Light pen","Joystick","Plotter","Scanner"],"answer":2,"explanation":"A plotter draws output on paper; light pens, joysticks and scanners feed data into the computer.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-53","question":"How many of these statements are correct? I. The TCP/IP model has four layers. II. ARPANET, the forerunner of the internet, began in 1969. III. HTML is a programming language. IV. Tim Berners-Lee proposed the World Wide Web in 1989.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: HTML is a markup language that describes page structure; it has no logic or control flow of its own.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-54","question":"Arrange these programming languages in the order they appeared, earliest first: 1. Java 2. COBOL 3. FORTRAN 4. C","options":["3, 2, 4, 1","2, 3, 4, 1","3, 4, 2, 1","2, 3, 1, 4"],"answer":0,"explanation":"FORTRAN (1957) → COBOL (1959) → C (1972) → Java (1995).","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-55","question":"Assertion (A): The BIOS of a computer is stored in ROM. Reason (R): ROM retains its contents even when the power is switched off.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Start-up firmware must survive power-off so the machine can boot, which is why it lives in non-volatile ROM (flash) rather than RAM.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-56","question":"Match the MS Word shortcut with its function: 1. Ctrl + Z 2. Ctrl + Y 3. Ctrl + U 4. Ctrl + P; a. Print b. Underline c. Redo d. Undo","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":0,"explanation":"Ctrl + Z undo, Ctrl + Y redo, Ctrl + U underline, Ctrl + P print.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-57","question":"How many of these statements are correct? I. The Linux kernel was created by Linus Torvalds. II. An operating system is a type of application software. III. Python is an interpreted language. IV. Open-source software must always be distributed free of cost.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. II is wrong (an OS is system software) and IV is wrong: open source means the source code is available under a licence; it may still be sold.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-58","question":"Which of the following numbers has the largest value?","options":["1F in hexadecimal","11111 in binary","37 in octal","32 in decimal"],"answer":3,"explanation":"1F₁₆ = 31, 11111₂ = 31 and 37₈ = 3 × 8 + 7 = 31, so 32 in decimal is the largest.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-59","question":"Which pair of term and description is NOT correctly matched?","options":["Phishing – fraudulent messages that trick users into revealing passwords","Trojan – malware disguised as a legitimate program","Worm – malware that needs a host file to spread","Firewall – system that filters network traffic"],"answer":2,"explanation":"A worm is self-replicating and spreads on its own across networks; it is a virus that attaches itself to a host file or program.","difficulty":"very-hard","source":"IBPS PO · IBPS Clerk · SSC CGL"},
  {"id": "comp-awareness-60", "question": "In MS Word, which shortcut selects all the text in a document?", "options": ["Ctrl + S", "Ctrl + A", "Ctrl + L", "Ctrl + E"], "answer": 1, "explanation": "Ctrl + A selects all. Ctrl + S saves, Ctrl + L left-aligns and Ctrl + E centres the text.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-61", "question": "PDF, a common file format for documents, stands for:", "options": ["Printable Document File", "Public Data Format", "Portable Document Format", "Personal Document Folder"], "answer": 2, "explanation": "Portable Document Format was developed by Adobe so that a document looks the same on any device or operating system.", "difficulty": "easy", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "comp-awareness-62", "question": "Which of the following is a web browser?", "options": ["MS Excel", "Mozilla Firefox", "Oracle", "Python"], "answer": 1, "explanation": "Firefox, Chrome, Edge and Safari are browsers. Excel is a spreadsheet, Oracle a database and Python a programming language.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-63", "question": "In Windows, which key combination opens the Task Manager directly?", "options": ["Ctrl + Alt + Tab", "Alt + F4", "Ctrl + Shift + Esc", "Windows + D"], "answer": 2, "explanation": "Ctrl + Shift + Esc opens Task Manager straight away. Alt + F4 closes the active window and Windows + D shows the desktop.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-64", "question": "In MS Excel, every formula must begin with the symbol:", "options": ["+", "#", "@", "="], "answer": 3, "explanation": "Typing = tells Excel that what follows is a formula, e.g. =SUM(A1:A5). Without it the entry is treated as text or a number.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-65", "question": "Which device connects different networks and forwards data packets between them using IP addresses?", "options": ["Hub", "Repeater", "Router", "Switch"], "answer": 2, "explanation": "A router works at the network layer and chooses paths between networks. A switch connects devices within one network using MAC addresses.", "difficulty": "moderate", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-66", "question": "In most Windows programs, which function key opens Help?", "options": ["F1", "F2", "F5", "F12"], "answer": 0, "explanation": "F1 opens Help. F2 renames a selected file, F5 refreshes, and F12 opens Save As in MS Office.", "difficulty": "moderate", "source": "SSC CHSL · IBPS Clerk"},
  {"id": "comp-awareness-67", "question": "The octal number 17 is equal to which decimal number?", "options": ["17", "15", "13", "7"], "answer": 1, "explanation": "17 in octal = 1 × 8 + 7 = 15 in decimal.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-68", "question": "Which protocol provides secure, encrypted remote login to another computer?", "options": ["Telnet", "SSH", "FTP", "SNMP"], "answer": 1, "explanation": "SSH (Secure Shell, port 22) encrypts the session. Telnet does the same job but sends everything, including passwords, as plain text.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-69", "question": "In MS Excel, which function counts only the cells in a range that contain numbers?", "options": ["COUNTA", "COUNT", "SUM", "COUNTBLANK"], "answer": 1, "explanation": "COUNT counts numeric cells only. COUNTA counts all non-empty cells, including text, and COUNTBLANK counts empty cells.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-70", "question": "Which type of memory must be refreshed thousands of times a second to keep its data?", "options": ["SRAM", "DRAM", "ROM", "Flash memory"], "answer": 1, "explanation": "DRAM stores each bit as charge on a tiny capacitor that leaks, so it needs constant refreshing. SRAM uses flip-flops and needs no refresh, which is why it is faster and used for cache.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-71", "question": "Virtual memory in a computer is:", "options": ["Memory built into the CPU registers", "A part of the hard disk used as an extension of RAM", "A type of ROM chip", "Memory available only on cloud servers"], "answer": 1, "explanation": "When RAM is full, the operating system moves less-used pages to a space on the disk (page file or swap), letting programs use more memory than is physically present, but more slowly.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-72", "question": "A CAPTCHA on a website is used to:", "options": ["Speed up page loading", "Tell human users apart from automated bots", "Encrypt passwords", "Store browsing history"], "answer": 1, "explanation": "CAPTCHA stands for Completely Automated Public Turing test to tell Computers and Humans Apart; it blocks automated sign-ups and spam.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-73", "question": "Spooling is most commonly used in computers for:", "options": ["Compressing files", "Queuing print jobs so that the CPU need not wait for the printer", "Scanning for viruses", "Defragmenting the hard disk"], "answer": 1, "explanation": "Spooling (Simultaneous Peripheral Operations On-Line) places jobs in a buffer on disk so that a slow device like a printer can take them one by one while the CPU continues working.", "difficulty": "hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-74", "question": "The binary equivalent of the decimal number 156 is:", "options": ["10011100", "10011010", "11001100", "10101100"], "answer": 0, "explanation": "156 = 128 + 16 + 8 + 4, so the bits for 128, 16, 8 and 4 are 1: 10011100.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-75", "question": "How many files of 4 MB each can be stored on a 2 GB pen drive? (1 GB = 1024 MB)", "options": ["500", "512", "256", "2048"], "answer": 1, "explanation": "2 GB = 2 × 1024 = 2048 MB. 2048 ÷ 4 = 512 files. 500 is the trap of taking 1 GB as 1000 MB.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-76", "question": "How many of these statements are correct? I. A MAC address is 48 bits long. II. A switch works at the data link layer of the OSI model. III. A hub sends incoming data only to the intended device. IV. Bluetooth is an example of a personal area network technology.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. A hub broadcasts data to every port; it is the switch that forwards data only to the intended device.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-77", "question": "Assertion (A): Phishing e-mails often contain links to fake websites that look like real bank sites. Reason (R): Phishing aims to steal sensitive data such as passwords and card details by pretending to be a trusted organisation.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The fake site is the tool used to trick users into entering their details, so R explains A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-78", "question": "Assertion (A): Data stored in RAM is lost when the power is switched off. Reason (R): RAM is made of magnetic disks.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: RAM is volatile. R is false: RAM is made of semiconductor chips; magnetic disks are used in hard disk drives, which keep data without power.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-79", "question": "Match the MS Word shortcut with its function: 1. Ctrl + F 2. Ctrl + H 3. Ctrl + K 4. Ctrl + N; a. New document b. Insert hyperlink c. Find d. Replace", "options": ["1-c, 2-b, 3-d, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-c, 2-d, 3-a, 4-b"], "answer": 1, "explanation": "Ctrl + F finds text, Ctrl + H opens Find and Replace, Ctrl + K inserts a hyperlink and Ctrl + N opens a new document.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-80", "question": "Match the malware with its description: 1. Trojan 2. Ransomware 3. Spyware 4. Keylogger; a. Records the keys a user presses b. Encrypts files and demands payment c. Pretends to be useful, legitimate software d. Secretly collects information about the user", "options": ["1-c, 2-b, 3-d, 4-a", "1-b, 2-c, 3-d, 4-a", "1-c, 2-d, 3-b, 4-a", "1-c, 2-b, 3-a, 4-d"], "answer": 0, "explanation": "A Trojan hides inside apparently genuine software, ransomware locks files for ransom, spyware watches the user and a keylogger records keystrokes (often to steal passwords).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-81", "question": "Which of the following is NOT a valid IPv4 address?", "options": ["10.0.0.1", "172.16.254.1", "192.168.1.256", "8.8.8.8"], "answer": 2, "explanation": "Each of the four octets in an IPv4 address is 8 bits, so it can range only from 0 to 255. 256 is out of range.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-82", "question": "Arrange in chronological order of first release: 1. Windows 95 2. MS-DOS 3. Android 4. Linux kernel", "options": ["2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1", "2, 4, 1, 3"], "answer": 3, "explanation": "MS-DOS 1981 → Linux kernel 1991 → Windows 95 in 1995 → first commercial Android phone 2008.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "comp-awareness-83", "question": "How many of these statements about MS Excel (2007 and later) are correct? I. $A$1 is an absolute cell reference. II. A worksheet has 1,048,576 rows. III. The last column of a worksheet is XFD. IV. The AVERAGE function ignores text in a range of cells.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct: a sheet has 1,048,576 rows and 16,384 columns (A to XFD), and AVERAGE skips text and empty cells in a referenced range.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO"},
  {"id": "comp-awareness-84", "question": "Ignoring overheads, how long does it take to download a 100 MB file on an 8 Mbps connection? (1 byte = 8 bits)", "options": ["12.5 seconds", "100 seconds", "800 seconds", "1 second"], "answer": 1, "explanation": "100 MB = 800 megabits. Time = 800 ÷ 8 = 100 s. 12.5 s is the trap of not converting bytes to bits.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk"},
  {"id": "comp-awareness-85", "question": "Who is known as the ‘father of the computer’ for designing the Analytical Engine?", "options": ["John von Neumann", "Blaise Pascal", "Charles Babbage", "Alan Turing"], "answer": 2, "explanation": "Charles Babbage designed the Difference Engine and the programmable Analytical Engine in the 19th century. Pascal built an early mechanical calculator, and Turing laid the theoretical foundations of computing.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-86", "question": "In MS PowerPoint, which key starts the slide show from the first slide?", "options": ["F12", "F1", "F7", "F5"], "answer": 3, "explanation": "F5 starts the show from the beginning and Shift + F5 from the current slide. F1 opens Help, F7 runs the spelling check and F12 opens Save As.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-87", "question": "In e-mail, ‘BCC’ stands for:", "options": ["Bulk Copy Command", "Backup Carbon Copy", "Blind Carbon Copy", "Basic Carbon Copy"], "answer": 2, "explanation": "Addresses in the BCC field receive the message but are hidden from all other recipients, unlike addresses in the To and CC fields.", "difficulty": "easy", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-88", "question": "Which logic gate is called a ‘universal gate’ because any other gate can be built from it alone?", "options": ["AND", "NAND", "OR", "XOR"], "answer": 1, "explanation": "NAND (and also NOR) is universal: NOT, AND and OR can all be made using only NAND gates. AND, OR and XOR cannot do this on their own.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-89", "question": "Which character-encoding standard is designed to represent the characters of almost all the world’s writing systems, including Devanagari?", "options": ["ASCII", "BCD", "Unicode", "EBCDIC"], "answer": 2, "explanation": "Unicode assigns a unique code point to over a hundred thousand characters from scripts worldwide. ASCII covers only 128 basic Latin characters, and EBCDIC is an old IBM code.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-90", "question": "In database systems, SQL stands for:", "options": ["System Query Library", "Standard Question Language", "Sequential Query Logic", "Structured Query Language"], "answer": 3, "explanation": "SQL is the standard language for creating, querying and updating relational databases, with commands such as SELECT, INSERT, UPDATE and DELETE.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-91", "question": "Moore’s law, stated by Gordon Moore, predicts that:", "options": ["Hard disk size grows tenfold every decade", "Computer prices halve every year", "The number of transistors on a chip doubles about every two years", "Internet speed doubles every six months"], "answer": 2, "explanation": "In 1965 Moore observed that transistor counts were doubling regularly, later revised to about every two years; this trend drove the rapid rise in computing power.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-92", "question": "A file with the extension .xlsx is created by default in:", "options": ["MS Access", "MS Excel", "MS PowerPoint", "MS Word"], "answer": 1, "explanation": ".xlsx is the default workbook format of Excel 2007 and later. Word uses .docx, PowerPoint .pptx and Access .accdb.", "difficulty": "moderate", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-93", "question": "The IEEE 802.11 family of standards defines:", "options": ["Ethernet (wired LAN)", "Bluetooth", "Wi-Fi (wireless LAN)", "USB"], "answer": 2, "explanation": "IEEE 802.11 covers wireless LANs, marketed as Wi-Fi. Wired Ethernet is IEEE 802.3, and Bluetooth was originally standardised as IEEE 802.15.1.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-94", "question": "The 4-bit two’s complement of the binary number 0101 is:", "options": ["1101", "1010", "0110", "1011"], "answer": 3, "explanation": "Two’s complement = one’s complement + 1: invert 0101 to 1010 and add 1 to get 1011, which represents −5. Stopping at 1010 gives only the one’s complement.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-95", "question": "Which MS Excel function looks for a value in the first column of a table and returns a value from another column in the same row?", "options": ["INDEX", "MATCH", "VLOOKUP", "HLOOKUP"], "answer": 2, "explanation": "VLOOKUP searches vertically down the first column; HLOOKUP searches along the first row. MATCH returns only the position of a value, and INDEX returns the value at a given position.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-96", "question": "Which of the following is an example of Software as a Service (SaaS)?", "options": ["Google App Engine", "A company’s own on-premises server", "Google Docs", "Amazon EC2 virtual machines"], "answer": 2, "explanation": "With SaaS the user simply uses a finished application in the browser, such as Google Docs or Gmail. EC2 rents raw computing (IaaS) and App Engine gives a platform for building apps (PaaS).", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-97", "question": "In a CPU, the program counter holds:", "options": ["The result of the last calculation", "The address of the next instruction to be fetched", "The number of programs being run", "The instruction now being decoded"], "answer": 1, "explanation": "After each fetch the program counter is updated to point to the next instruction. The instruction being decoded sits in the instruction register, and results go to the accumulator or other registers.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-98", "question": "PARAM 8000, India’s first supercomputer, was built in 1991 by:", "options": ["BARC", "C-DAC", "ISRO", "IIT Bombay"], "answer": 1, "explanation": "The Centre for Development of Advanced Computing, Pune, built PARAM 8000 under Vijay Bhatkar after India was denied a Cray supercomputer. Later PARAM systems continue the series.", "difficulty": "hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-99", "question": "Restarting a computer that is already switched on, for example with the Restart option or Ctrl + Alt + Del, is called:", "options": ["Warm booting", "Hibernation", "Cold booting", "Formatting"], "answer": 0, "explanation": "Warm (soft) booting reloads the operating system without cutting the power. Cold booting starts the computer from a fully switched-off state.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-100", "question": "Which of the following is a private IPv4 address that cannot be routed on the public internet?", "options": ["11.0.0.1", "192.168.10.5", "172.32.0.1", "8.8.8.8"], "answer": 1, "explanation": "The private ranges are 10.0.0.0–10.255.255.255, 172.16.0.0–172.31.255.255 and 192.168.0.0–192.168.255.255. 172.32.0.1 lies just outside the 172 range, and 8.8.8.8 is Google’s public DNS server.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-101", "question": "Software that is distributed free for a trial period, after which the user is expected to pay for it, is called:", "options": ["Firmware", "Open-source software", "Shareware", "Freeware"], "answer": 2, "explanation": "Shareware is ‘try before you buy’. Freeware is free with no payment expected, open-source software makes its source code available, and firmware is software stored in hardware such as ROM.", "difficulty": "hard", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-102", "question": "A digital signature on an electronic document mainly ensures:", "options": ["That the document cannot be printed", "The identity of the signer and that the document has not been altered", "That the document is compressed", "That the document is encrypted so nobody else can read it"], "answer": 1, "explanation": "A digital signature uses the signer’s private key, and anyone can check it with the public key; it gives authenticity, integrity and non-repudiation but does not by itself keep the content secret.", "difficulty": "hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-103", "question": "How many of these statements about logic gates are correct? I. NOR is a universal gate. II. The output of an XOR gate is 1 when its two inputs are different. III. A NOT gate has two inputs. IV. The output of an AND gate is 1 only when all its inputs are 1.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. III is wrong: a NOT gate (inverter) has a single input whose value it reverses.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-104", "question": "The product of the binary numbers 1011 and 101 is:", "options": ["110111", "111011", "101101", "110011"], "answer": 0, "explanation": "1011 = 11 and 101 = 5 in decimal; 11 × 5 = 55 = 32 + 16 + 4 + 2 + 1 = 110111 in binary.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-105", "question": "Match the database term with its meaning: 1. Primary key 2. Foreign key 3. Tuple 4. Attribute; a. A column of a table b. A row of a table c. A field that refers to the primary key of another table d. A field that uniquely identifies each record", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "A primary key uniquely identifies each record; a foreign key links to another table’s primary key; in relational terms a tuple is a row (record) and an attribute is a column (field).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-106", "question": "Assertion (A): A solid-state drive (SSD) usually reads and writes data much faster than a hard disk drive (HDD). Reason (R): An SSD stores data in flash memory chips and has no moving parts.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "An HDD must spin its platters and move a read–write head to the data, while an SSD reaches any location electronically, so access is far faster. R explains A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-107", "question": "Arrange in chronological order: 1. Release of the IBM Personal Computer 2. Founding of Google 3. Unveiling of ENIAC 4. Tim Berners-Lee’s proposal for the World Wide Web", "options": ["1, 3, 4, 2", "3, 4, 1, 2", "3, 1, 2, 4", "3, 1, 4, 2"], "answer": 3, "explanation": "ENIAC was unveiled in 1946, the IBM PC came out in 1981, the World Wide Web was proposed in 1989 and Google was founded in 1998.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-108", "question": "An uncompressed image of 1024 × 768 pixels uses 24-bit colour. Its size is (1 MB = 1024 × 1024 bytes):", "options": ["0.75 MB", "2.25 MB", "18 MB", "24 MB"], "answer": 1, "explanation": "Each pixel needs 24 bits = 3 bytes. Size = 1024 × 768 × 3 = 2,359,296 bytes = 2,359,296 ÷ 1,048,576 = 2.25 MB. Forgetting to convert bits to bytes gives 18 MB.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-109", "question": "How many of these statements about e-mail are correct? I. Recipients in the CC field are visible to all other recipients. II. Recipients in the BCC field are hidden from the other recipients. III. By default, IMAP downloads messages and deletes them from the server. IV. POP3 is the protocol used to send e-mail.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. IMAP keeps mail on the server and syncs it across devices; downloading and deleting is typical of POP3, which is a protocol for receiving mail. Mail is sent with SMTP.", "difficulty": "very-hard", "source": "IBPS Clerk · SBI Clerk · SSC CHSL"},
  {"id": "comp-awareness-110", "question": "Which of the following is NOT a function of an operating system?", "options": ["Compiling a program’s source code into machine code", "Memory management", "Scheduling processes on the CPU", "Managing files and folders"], "answer": 0, "explanation": "Compiling is done by a compiler, a separate language translator. The operating system manages memory, processes, files, devices and security.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-111", "question": "The hexadecimal number 3A is equal to which octal number?", "options": ["72", "71", "112", "58"], "answer": 0, "explanation": "3A₁₆ = 3 × 16 + 10 = 58 in decimal; 58 = 7 × 8 + 2, so it is 72 in octal. 58 is the decimal value, the usual trap.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-112", "question": "Assertion (A): Hexadecimal notation is widely used to write binary data such as memory addresses compactly. Reason (R): Each hexadecimal digit corresponds to exactly four binary digits.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because 16 = 2⁴, every group of four bits maps to one hex digit, so a 32-bit address fits in 8 hex digits and conversion is trivial. R explains A.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id": "comp-awareness-113", "question": "How many of these statements about cyber security are correct? I. A firewall can be implemented in hardware or in software. II. Two-factor authentication combines two different kinds of proof, such as a password and an OTP. III. In symmetric-key encryption the same key is used to encrypt and decrypt. IV. HTTPS sends data over the network as plain text.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: HTTPS encrypts traffic using TLS; it is plain HTTP that sends data as readable text.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · RRB NTPC"},
  {"id": "comp-awareness-114", "question": "Match the MS Excel function with what it does: 1. SUMIF 2. CONCAT 3. TRIM 4. NOW; a. Returns the current date and time b. Removes extra spaces from text c. Joins several text strings into one d. Adds the cells that meet a given condition", "options": ["1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a", "1-d, 2-b, 3-c, 4-a"], "answer": 2, "explanation": "SUMIF adds cells that meet a condition, CONCAT joins text, TRIM leaves only single spaces between words, and NOW returns the current date and time (TODAY returns only the date).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · IBPS Clerk"},
  {"id":"comp-awareness-115","question":"Which generation of computers used integrated circuits (ICs) as the main electronic component?","options":["Fifth generation","First generation","Second generation","Third generation"],"answer":3,"explanation":"Third-generation computers (mid-1960s to early 1970s) used ICs. The first used vacuum tubes, the second transistors, and the fourth microprocessors (VLSI).","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-116","question":"A device that works at the Data Link layer and forwards frames only to the port where the destination MAC address is connected is a:","options":["Hub","Switch","Repeater","Modem"],"answer":1,"explanation":"A switch learns MAC addresses and forwards each frame to the right port. A hub simply repeats every signal to all ports (Physical layer), as does a repeater.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-117","question":"How many layers does the OSI reference model have?","options":["7","4","5","6"],"answer":0,"explanation":"The OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation and Application. The TCP/IP model is the one usually described with 4 layers.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-118","question":"Which of the following storage units is the largest?","options":["1 Gigabyte","1 Terabyte","1 Petabyte","1000 Megabytes"],"answer":2,"explanation":"Order: MB < GB < TB < PB. 1 PB = 1024 TB, so it is the largest; 1000 MB is less than 1 GB.","difficulty":"easy","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-119","question":"What is the decimal value of the binary number 1101.101?","options":["13.625","13.5","11.625","13.75"],"answer":0,"explanation":"1101 = 8+4+0+1 = 13; .101 = 1/2 + 0/4 + 1/8 = 0.625. Total 13.625. 13.75 would be .110.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-120","question":"Convert (777)₈ into base 10.","options":["777","511","512","448"],"answer":1,"explanation":"7×64 + 7×8 + 7 = 448 + 56 + 7 = 511. It is one less than 8³ = 512, just as 999 is one less than 10³.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-121","question":"Which Boolean expression is equal to A + A·B?","options":["A·B","B","A","A + B"],"answer":2,"explanation":"By the absorption law, A + AB = A(1 + B) = A·1 = A. A + B would come from A + A'B, a different expression.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-122","question":"A logic gate gives output 1 only when its two inputs are different. The gate is:","options":["OR","XNOR","NAND","XOR"],"answer":3,"explanation":"XOR (exclusive OR) is 1 for inputs 01 and 10. XNOR is its complement (1 when inputs are equal); OR is also 1 for input 11.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-123","question":"In the OSI model, encryption, compression and translation of data formats are functions of which layer?","options":["Transport layer","Session layer","Application layer","Presentation layer"],"answer":3,"explanation":"The Presentation layer (layer 6) handles data representation: translation, encryption and compression. The Session layer manages dialogue/sessions; the Transport layer handles end-to-end delivery.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-124","question":"Standard ASCII uses how many bits to represent a character, and so how many characters can it represent?","options":["16 bits, 65,536 characters","8 bits, 256 characters","7 bits, 128 characters","6 bits, 64 characters"],"answer":2,"explanation":"Standard ASCII is a 7-bit code with 2⁷ = 128 characters. 8-bit/256 describes 'extended ASCII', a common trap.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-125","question":"A single-layer, single-sided DVD has a standard capacity of about:","options":["700 MB","4.7 GB","25 GB","8.5 GB"],"answer":1,"explanation":"A single-layer DVD stores about 4.7 GB. 700 MB is a CD, 25 GB a single-layer Blu-ray disc, and 8.5 GB a dual-layer DVD.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-126","question":"In the IPv4 address 127.0.0.1, the address refers to:","options":["The loopback address of the local computer itself","The default gateway of the network","A public web server","The broadcast address of a class A network"],"answer":0,"explanation":"The 127.0.0.0/8 block is reserved for loopback; 127.0.0.1 ('localhost') points back to the same machine. It is never a gateway or public address.","difficulty":"moderate","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-127","question":"What is the 8-bit two's complement representation of −5?","options":["10000101","11111010","11111011","00000101"],"answer":2,"explanation":"+5 = 00000101; one's complement = 11111010; add 1 → 11111011. 11111010 is only the one's complement, and 10000101 is the sign-magnitude form.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-128","question":"The hexadecimal number ABC is equal to which decimal number?","options":["2478","2748","2740","3020"],"answer":1,"explanation":"A=10, B=11, C=12: 10×256 + 11×16 + 12 = 2560 + 176 + 12 = 2748.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-129","question":"The decimal fraction 0.375 written in binary is:","options":["0.110","0.101","0.0011","0.011"],"answer":3,"explanation":"0.375×2 = 0.75 → 0; 0.75×2 = 1.5 → 1; 0.5×2 = 1.0 → 1. Reading the integer parts in order gives 0.011 (= 1/4 + 1/8).","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-130","question":"What is the result of the binary subtraction 11010 − 1101?","options":["1101","1011","1111","10011"],"answer":0,"explanation":"11010 = 26 and 1101 = 13; 26 − 13 = 13 = 1101 in binary.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-131","question":"The Binary Coded Decimal (8421 BCD) representation of the decimal number 59 is:","options":["0111 0011","0011 1011","0101 1010","0101 1001"],"answer":3,"explanation":"In BCD each decimal digit is coded separately in 4 bits: 5 = 0101, 9 = 1001. 0011 1011 is the pure binary of 59, a common trap.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-132","question":"A memory chip has 16 address lines and each location stores 1 byte. Its capacity is:","options":["32 KB","16 KB","64 KB","128 KB"],"answer":2,"explanation":"16 address lines can select 2¹⁶ = 65,536 locations; at 1 byte each, that is 65,536 bytes = 64 KB.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-133","question":"What is the minimum number of bits needed to give a unique binary code to 1000 different items?","options":["10","9","11","1000"],"answer":0,"explanation":"2⁹ = 512 is too small and 2¹⁰ = 1024 is enough, so 10 bits are needed.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-134","question":"The range of integers that can be stored in 8 bits using two's complement is:","options":["−127 to +127","−128 to +127","0 to 255","−256 to +255"],"answer":1,"explanation":"Two's complement in n bits covers −2ⁿ⁻¹ to 2ⁿ⁻¹ − 1, i.e. −128 to +127. −127 to +127 is the range in sign-magnitude or one's complement, which have two zeros.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-135","question":"By De Morgan's theorem, the complement of (A + B) is equal to:","options":["A′ + B′","A′ · B′","A · B","(A · B)′"],"answer":1,"explanation":"(A + B)′ = A′·B′, which is why a NOR gate equals an AND gate with inverted inputs. A′ + B′ is the complement of A·B, the other De Morgan law.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-136","question":"In which situation does an operating system suffer from 'thrashing'?","options":["The hard disk develops bad sectors","Two processes wait forever for resources held by each other","A low-priority process never gets the CPU","It spends more time swapping pages between memory and disk than executing processes"],"answer":3,"explanation":"Thrashing is excessive paging when processes do not have enough frames. Processes waiting on each other is deadlock; a process never getting the CPU is starvation.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-137","question":"In a class C network with subnet mask 255.255.255.0, how many usable host addresses are available?","options":["254","256","255","253"],"answer":0,"explanation":"8 host bits give 2⁸ = 256 addresses, minus the network address and the broadcast address = 254 usable hosts.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-138","question":"Which program combines several object files and library routines into a single executable file?","options":["Assembler","Loader","Linker","Interpreter"],"answer":2,"explanation":"The linker joins object modules into one executable. The loader then places the executable in memory to run it; the assembler converts assembly into object code.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-139","question":"TCP and UDP are protocols of which OSI layer, and which of them guarantees ordered, reliable delivery?","options":["Transport layer; TCP","Network layer; UDP","Transport layer; UDP","Session layer; TCP"],"answer":0,"explanation":"Both work at the Transport layer. TCP is connection-oriented with acknowledgements and ordering; UDP is connectionless and faster but unreliable.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-140","question":"The Excess-3 code of the decimal digit 4 is:","options":["1000","0100","0011","0111"],"answer":3,"explanation":"Excess-3 adds 3 to the digit before converting: 4 + 3 = 7 = 0111. 0100 is plain BCD of 4.","difficulty":"hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-141","question":"A processor negates the 8-bit value 00101100 using two's complement. Which bit pattern does it produce?","options":["11010011","11010100","11010101","10101100"],"answer":1,"explanation":"One's complement of 00101100 is 11010011; adding 1 gives 11010100. 11010011 is only the one's complement. Check: 00101100 + 11010100 = 1 00000000 (carry discarded).","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-142","question":"The binary number 1011 converted into Gray code is:","options":["1011","1101","1110","0110"],"answer":2,"explanation":"Gray code: keep the MSB (1), then XOR each pair of adjacent bits: 1⊕0 = 1, 0⊕1 = 1, 1⊕1 = 0. Result 1110.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-143","question":"(FF)₁₆ + (1)₁₆ − (100)₈ equals which decimal number?","options":["156","256","192","200"],"answer":2,"explanation":"FF + 1 = 100₁₆ = 256; 100₈ = 64. 256 − 64 = 192. Reading 100₈ as 100 decimal gives the trap 156.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-144","question":"What is the product of the binary numbers 1010 and 111, expressed in binary?","options":["1010111","1000110","1000100","111110"],"answer":1,"explanation":"1010 = 10 and 111 = 7; 10 × 7 = 70 = 64 + 4 + 2 = 1000110.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-145","question":"A network uses the subnet mask 255.255.255.192 (/26). How many usable host addresses does each subnet have?","options":["30","64","126","62"],"answer":3,"explanation":"/26 leaves 32 − 26 = 6 host bits: 2⁶ = 64 addresses minus network and broadcast = 62. 126 is for /25 and 30 for /27.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-146","question":"A 32-bit memory address is written in hexadecimal. How many hexadecimal digits does it take, and what is the largest address?","options":["8 digits; FFFFFFFF","4 digits; FFFF","8 digits; 99999999","16 digits; FFFFFFFFFFFFFFFF"],"answer":0,"explanation":"Each hex digit stands for 4 bits, so 32 bits need 8 hex digits; the largest is all ones = FFFFFFFF. 99999999 is not the maximum since hex digits go up to F.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-147","question":"Convert (345)₈ directly into base 16.","options":["159","D5","E5","E9"],"answer":2,"explanation":"345₈ = 011 100 101 in binary = 1110 0101 regrouped in fours = E5₁₆. Check: 3×64 + 4×8 + 5 = 229 = 14×16 + 5. 159 is just a wrong regrouping.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-148","question":"In which of the following is the Boolean identity stated INCORRECTLY?","options":["A + A′·B = A·B","A·(A + B) = A","A + A′ = 1","(A′)′ = A"],"answer":0,"explanation":"A + A′B simplifies to A + B, not AB. The others are correct: absorption A(A+B) = A, the complement law A + A′ = 1, and double complement (A′)′ = A.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-149","question":"A NAND gate has its two inputs tied together and fed with the signal X. The output is:","options":["X (it acts as a buffer)","X′ (it acts as a NOT gate)","Always 1","Always 0"],"answer":1,"explanation":"(X·X)′ = X′, so a NAND with joined inputs is an inverter — the first step in showing NAND is universal. It is always 1 only when at least one input is 0.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-150","question":"How many of these statements about computer memory are correct? I. SRAM is used for cache and does not need refreshing. II. EEPROM can be erased electrically, byte by byte. III. Flash memory is a type of EEPROM. IV. Registers are slower than cache memory.","options":["Only one","Only two","All four","Only three"],"answer":3,"explanation":"I, II and III are correct. IV is wrong — registers sit inside the CPU and are the fastest memory of all, faster than cache.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-151","question":"A sound file is recorded at 44,100 samples per second, 16 bits per sample, in stereo (2 channels). Ignoring compression, how many bytes does one second of audio take?","options":["7,05,600 bytes","88,200 bytes","14,11,200 bytes","1,76,400 bytes"],"answer":3,"explanation":"44,100 × 16 × 2 = 14,11,200 bits per second; ÷ 8 = 1,76,400 bytes. 14,11,200 is the bit figure, a trap for forgetting to divide by 8; 88,200 forgets the second channel.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-152","question":"Which of these is the correct order of the OSI layers from the bottom (layer 1) up to layer 4?","options":["Data Link, Physical, Transport, Network","Physical, Network, Data Link, Transport","Physical, Data Link, Network, Transport","Physical, Data Link, Transport, Network"],"answer":2,"explanation":"Layer 1 Physical, 2 Data Link, 3 Network, 4 Transport, then Session, Presentation and Application.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-153","question":"How many of these statements about IPv4 addressing are correct? I. A class A address has a first octet from 1 to 126. II. 172.16.5.4 is a private address. III. 192.168.10.0/24 has 256 usable host addresses. IV. 255.255.255.255 is a limited broadcast address.","options":["Only three","All four","Only two","Only one"],"answer":0,"explanation":"I, II and IV are correct (127 is reserved for loopback; 172.16–31.x.x is a private range). III is wrong: a /24 has 256 addresses but only 254 usable hosts.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-154","question":"The decimal number 45 is stored as an 8-bit unsigned binary number and then shifted left by 2 bits (zeros entering from the right, no overflow). The new decimal value is:","options":["90","180","47","11"],"answer":1,"explanation":"45 = 00101101; shifting left by 2 gives 10110100 = 128 + 32 + 16 + 4 = 180. Each left shift doubles the value, so 45 × 4 = 180. 11 would come from a right shift by 2.","difficulty":"very-hard","source":"SBI PO · IBPS Clerk · SSC CGL"},
  {"id":"comp-awareness-155","question":"Convert the hexadecimal number (2F7)₁₆ directly into octal.","options":["(1367)₈","(1357)₈","(1377)₈","(2367)₈"],"answer":0,"explanation":"2F7 = 0010 1111 0111; regrouping in threes from the right gives 001 011 110 111 = 1 3 6 7, so (1367)₈ (= 759 in decimal).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-156","question":"A cache has an access time of 10 ns and main memory 100 ns. The cache is checked first and, on a miss, the word is then read from main memory, so a miss costs 10 + 100 ns. With a hit ratio of 90%, what is the average memory access time?","options":["19 ns","20 ns","91 ns","55 ns"],"answer":1,"explanation":"Average = 0.9 × 10 + 0.1 × (10 + 100) = 9 + 11 = 20 ns. 19 ns comes from wrongly charging a miss only 100 ns, as if both memories were searched in parallel.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-157","question":"In the fetch phase of an instruction cycle, which register-to-register transfer happens first?","options":["The memory data register (MDR) is copied into the program counter (PC)","The instruction register (IR) is copied into the MDR","The program counter (PC) is copied into the memory address register (MAR)","The MAR is copied into the program counter (PC)"],"answer":2,"explanation":"The PC holds the address of the next instruction, so it is sent to the MAR to read memory; the fetched word arrives in the MDR and then moves to the IR.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-158","question":"A processor has a 20-bit address bus, and its memory is word-addressable with 16-bit (2-byte) words. What is the maximum memory it can address?","options":["1 MB","512 KB","16 MB","2 MB"],"answer":3,"explanation":"20 address lines select 2²⁰ words, and each word is 2 bytes, so 2²⁰ × 2 B = 2 MB. Answering 1 MB wrongly assumes each address holds one byte.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-159","question":"A system uses 32-bit virtual addresses and a page size of 4 KB. How many bits of the address form the page number and how many the offset within the page?","options":["20-bit page number, 12-bit offset","12-bit page number, 20-bit offset","22-bit page number, 10-bit offset","24-bit page number, 8-bit offset"],"answer":0,"explanation":"4 KB = 2¹² bytes, so 12 bits are needed for the offset; the remaining 32 − 12 = 20 bits give the page number (2²⁰ pages).","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-160","question":"Which of the following is NOT one of the four conditions that must all hold for a deadlock to occur?","options":["Mutual exclusion","Hold and wait","Circular wait","Pre-emption of resources"],"answer":3,"explanation":"The necessary conditions are mutual exclusion, hold and wait, NO pre-emption and circular wait. If resources can be pre-empted, deadlock can be broken, so pre-emption is not a condition for it.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-161","question":"Three processes arrive at time 0 in the order P1 (burst 10 ms), P2 (burst 4 ms) and P3 (burst 2 ms). By how much does the average waiting time under non-pre-emptive SJF fall compared with FCFS?","options":["8 ms","5.33 ms","2.67 ms","16 ms"],"answer":1,"explanation":"FCFS waits are 0, 10, 14 (average 8 ms); SJF runs P3, P2, P1 with waits 0, 2, 6 (average 2.67 ms). The fall is 8 − 2.67 = 5.33 ms; 16 ms is the fall in TOTAL waiting time, not the average.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-162","question":"In a STUDENT table, both RollNo and Email can uniquely identify every row. The designer chooses RollNo as the primary key. What is Email now called?","options":["A foreign key","A composite key","An alternate key","A surrogate key"],"answer":2,"explanation":"Every minimal unique identifier is a candidate key; the candidate keys not chosen as the primary key are alternate keys. A surrogate key is an artificial system-generated id, which Email is not.","difficulty":"moderate","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-163","question":"A relation is in 1NF and its primary key consists of a single attribute. Which normal form is it then guaranteed to satisfy?","options":["2NF","3NF","BCNF","None beyond 1NF"],"answer":0,"explanation":"2NF forbids partial dependency on part of a composite key; with a single-attribute key there is no 'part', so the relation is automatically in 2NF. It can still have transitive dependencies, so 3NF is not guaranteed.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-164","question":"A funds-transfer transaction commits successfully, and a second later the database server loses power. When it restarts, the transfer is still recorded. Which ACID property ensured this?","options":["Atomicity","Durability","Consistency","Isolation"],"answer":1,"explanation":"Durability guarantees that once a transaction commits, its changes survive later failures. Atomicity is about all-or-nothing execution before commit, not survival after it.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-165","question":"Which network device is matched with the WRONG OSI layer at which it mainly operates?","options":["Hub — Physical layer","Bridge — Data Link layer","Router — Network layer","Repeater — Network layer"],"answer":3,"explanation":"A repeater only regenerates the electrical signal, so it works at the Physical layer (layer 1), not the Network layer. The other three pairs are correct.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-166","question":"An IPv6 address is written as colon-separated groups of hexadecimal digits. In full (uncompressed) form, how many groups are there and how many bits does each group carry?","options":["16 groups of 8 bits","4 groups of 32 bits","8 groups of 16 bits","6 groups of 16 bits"],"answer":2,"explanation":"IPv6 is 128 bits, written as 8 groups of 4 hex digits; 4 hex digits = 16 bits, and 8 × 16 = 128. Six groups is the pattern of a 48-bit MAC address, not IPv6.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-167","question":"In a 48-bit MAC address, what do the first 24 bits (the Organisationally Unique Identifier) identify?","options":["The network to which the device is connected","The manufacturer of the network interface","The subnet mask of the device","The country where the device was registered"],"answer":1,"explanation":"The OUI is assigned to the manufacturer (vendor); the last 24 bits are the serial number given by that vendor. MAC addresses carry no network or subnet information; that is the job of IP addressing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-168","question":"The 8-bit pattern 11110110 stores a signed integer in two's complement form. What is its value?","options":["−118","246","−10","−9"],"answer":2,"explanation":"The MSB is 1, so it is negative; inverting and adding 1 gives 00001010 = 10, so the value is −10. −118 is the sign-magnitude reading, 246 the unsigned reading and −9 the one's-complement reading.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-169","question":"The Gray code 1101 is converted back into ordinary binary. What is the result?","options":["1011","1110","1101","1001"],"answer":3,"explanation":"Keep the first bit (1), then each binary bit = previous binary bit XOR current Gray bit: 1, 1⊕1 = 0, 0⊕0 = 0, 0⊕1 = 1, giving 1001. 1011 is what you get by converting binary to Gray instead.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-170","question":"What is (7A)₁₆ + (2C)₁₆, written in hexadecimal?","options":["A6","96","166","B6"],"answer":0,"explanation":"A + C = 10 + 12 = 22 = 16 + 6, so write 6 and carry 1; 7 + 2 + 1 = 10 = A, giving A6. 96 forgets the carry, and 166 is the decimal value of A6, not a hex result.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-171","question":"How many of these gates are 'universal', i.e. able to build every other logic function on their own: NAND, NOR, XOR, AND?","options":["One","Three","Two","Four"],"answer":2,"explanation":"Only NAND and NOR are universal. AND alone cannot make NOT, and XOR alone cannot make AND, so they are not universal.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-172","question":"Which type of ROM is erased by exposing the chip to ultraviolet light through a small quartz window on its package?","options":["EEPROM","PROM","Mask ROM","EPROM"],"answer":3,"explanation":"EPROM is erased with UV light and then reprogrammed. EEPROM (and flash) is erased electrically, while PROM is one-time programmable and mask ROM is fixed at manufacture.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-173","question":"Assertion (A): Dynamic RAM must be refreshed thousands of times every second. Reason (R): DRAM stores each bit as charge in a tiny capacitor, and the charge leaks away.","options":["A is true but R is false","Both A and R are true, but R is not the correct explanation of A","A is false but R is true","Both A and R are true, and R is the correct explanation of A"],"answer":3,"explanation":"DRAM cells are capacitors whose charge leaks within milliseconds, which is exactly why they must be refreshed. SRAM uses flip-flops and needs no refresh.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-174","question":"Which sequence correctly describes what happens when a PC is switched on?","options":["Power-on self-test (POST) → boot loader runs → operating system kernel loads → user login","Boot loader runs → POST → kernel loads → user login","Kernel loads → POST → boot loader runs → user login","POST → kernel loads → boot loader runs → user login"],"answer":0,"explanation":"Firmware (BIOS/UEFI) first runs the POST, then finds and runs the boot loader, which loads the OS kernel; only then is the user offered a login. The kernel cannot load before the boot loader that loads it.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-175","question":"In which order does a compiler normally carry out these phases on a source program?","options":["Syntax analysis → lexical analysis → semantic analysis → code generation","Lexical analysis → semantic analysis → syntax analysis → code generation","Lexical analysis → syntax analysis → semantic analysis → code generation","Lexical analysis → syntax analysis → code generation → semantic analysis"],"answer":2,"explanation":"The source is first split into tokens (lexical), then tokens are arranged into a parse tree (syntax), then checked for meaning such as types (semantic), and only then is code generated.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-176","question":"A 5-stage instruction pipeline takes one clock cycle per stage and never stalls. How many clock cycles does it need to complete 100 instructions?","options":["500","104","105","100"],"answer":1,"explanation":"The first instruction needs 5 cycles to fill the pipeline, and each of the remaining 99 finishes one cycle later: 5 + 99 = 104. 500 is the count without pipelining.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-177","question":"How many of these statements about RISC and CISC processors are correct? I. RISC designs usually use fixed-length instructions. II. CISC designs offer more addressing modes. III. RISC follows a load/store design, where only load and store instructions access memory. IV. Every CISC instruction completes in one clock cycle.","options":["One","Two","Four","Three"],"answer":3,"explanation":"I, II and III are correct. IV is false: complex CISC instructions often take many cycles; single-cycle execution is a RISC goal.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-178","question":"The Boolean expression A'B + AB' + AB (where ' means NOT) simplifies to which single operation on A and B?","options":["A OR B","A XOR B","A AND B","NOT A OR NOT B"],"answer":0,"explanation":"AB' + AB = A(B' + B) = A, so the expression becomes A + A'B = A + B, i.e. A OR B. XOR would be only the first two terms; the extra AB term adds the case A = B = 1.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-179","question":"A hard disk spins at 7200 rpm and has an average seek time of 8 ms. Ignoring transfer and controller time, what is its average access time?","options":["16.33 ms","8.33 ms","12.17 ms","4.17 ms"],"answer":2,"explanation":"One rotation takes 60,000 ÷ 7200 = 8.33 ms, and on average the head waits half a rotation (4.17 ms). Access time = 8 + 4.17 ≈ 12.17 ms; 16.33 ms wrongly adds a full rotation.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-180","question":"How many of these statements are correct? I. A solid-state drive has no moving read/write head. II. Flash memory cells can be rewritten only a limited number of times. III. SSDs should be defragmented regularly to keep them fast. IV. Random reads are much faster on an SSD than on a hard disk.","options":["Two","Three","One","Four"],"answer":1,"explanation":"I, II and IV are true. III is false: an SSD has no seek time, so fragmentation hardly slows it, and needless defragmentation only wears out its limited write cycles.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-181","question":"In a virtual memory system, a 'page fault' occurs when a program refers to a page that:","options":["is not present in the cache memory","has no entry in the translation lookaside buffer (TLB)","belongs to the address space of another process","is not currently loaded in main memory"],"answer":3,"explanation":"A page fault means the page is on disk, not in RAM, so the OS must load it. A TLB miss only means the translation must be read from the page table; the page may well be in RAM.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-182","question":"A program reads the elements of a large array one after another: a[0], a[1], a[2] and so on. Which property does the cache exploit to speed this up?","options":["Spatial locality","Temporal locality","Thrashing","Write-back"],"answer":0,"explanation":"Neighbouring addresses are used soon after one another, so loading a whole cache block at once helps: that is spatial locality. Temporal locality is reuse of the SAME address, such as a loop counter.","difficulty":"moderate","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-183","question":"Under a write-back cache policy, when is a modified cache block written to main memory?","options":["Immediately, on every write to the block","Only when the block is about to be replaced, as shown by its dirty bit","Only when the program terminates","Never; main memory is updated by the DMA controller"],"answer":1,"explanation":"Write-back marks a changed block 'dirty' and copies it to memory only when it is evicted. Writing on every update is the write-through policy.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-184","question":"How many of these statements about the system bus are correct? I. The address bus carries addresses from the CPU to memory, so it is unidirectional. II. The data bus is bidirectional. III. The width of the data bus decides how much memory can be addressed. IV. Read and write signals travel on the control bus.","options":["Three","Two","One","Four"],"answer":0,"explanation":"I, II and IV are correct. III is wrong: the ADDRESS bus width sets the addressable memory (n lines give 2ⁿ locations); the data bus width sets how many bits move at a time.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-185","question":"Convert (563)₈ directly into hexadecimal.","options":["(371)₁₆","(1B3)₁₆","(163)₁₆","(173)₁₆"],"answer":3,"explanation":"563 = 101 110 011 in binary; regroup in fours from the right: 1 0111 0011 = 1 7 3, so (173)₁₆. 371 is the decimal value, not hex.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-186","question":"The decimal number 156 is stored once in pure binary and once in 8421 BCD. How many more bits does the BCD form need?","options":["None","Two","Four","Three"],"answer":2,"explanation":"156 in binary is 10011100 (8 bits). BCD codes each digit in 4 bits: 0001 0101 0110 (12 bits). The difference is 4 bits.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-187","question":"What is the largest unsigned number that 12 bits can hold, written in octal?","options":["(7777)₈","(4095)₈","(777)₈","(3777)₈"],"answer":0,"explanation":"The largest 12-bit value is 2¹² − 1 = 4095 = 111 111 111 111, and each group of three 1s is 7, giving (7777)₈. '4095' is the decimal value and is not even a valid octal numeral.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-188","question":"Which of these IPv4 addresses is a PRIVATE address that cannot be routed on the public internet?","options":["172.32.1.1","192.169.1.1","172.20.5.4","11.0.0.1"],"answer":2,"explanation":"The private ranges are 10.0.0.0/8, 172.16.0.0–172.31.255.255 and 192.168.0.0/16. 172.20.5.4 lies inside 172.16–172.31; 172.32 is just outside it, and 192.169 and 11 are public.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-189","question":"Six computers are joined in a full mesh topology. How many cables are needed, and how many ports must each computer have?","options":["30 cables, 5 ports each","15 cables, 6 ports each","30 cables, 6 ports each","15 cables, 5 ports each"],"answer":3,"explanation":"Each pair needs one link: 6 × 5 ÷ 2 = 15 cables, and each computer connects to the other 5, so it needs 5 ports. 30 counts every cable twice.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-190","question":"A bank must link two buildings that sit next to a power substation causing heavy electrical noise. Which cable is the best choice?","options":["Unshielded twisted pair","Coaxial cable","Optical fibre","Shielded twisted pair"],"answer":2,"explanation":"Optical fibre carries light, not electrical signals, so electromagnetic interference cannot affect it. Shielding on copper cables only reduces interference; it does not remove it.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-191","question":"The 'ping' command checks whether a host can be reached. Which protocol do its echo request and echo reply messages use?","options":["ICMP","TCP","UDP","ARP"],"answer":0,"explanation":"Ping sends ICMP Echo Request messages and waits for Echo Replies. ICMP is a network-layer control protocol and uses no TCP or UDP port; ARP only maps IP to MAC on a LAN.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-192","question":"A walkie-talkie, a television broadcast and an ordinary telephone call are examples of which transmission modes, respectively?","options":["Simplex, half-duplex, full-duplex","Full-duplex, simplex, half-duplex","Half-duplex, simplex, full-duplex","Half-duplex, full-duplex, simplex"],"answer":2,"explanation":"Walkie-talkie users talk in turn (half-duplex), TV flows only one way (simplex), and both phone callers can speak at once (full-duplex).","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-193","question":"Ten users must each be able to talk privately with every other user. How many keys are needed in total with symmetric-key encryption, and how many with public-key encryption?","options":["20 and 45","45 and 20","90 and 20","45 and 10"],"answer":1,"explanation":"Symmetric: one shared secret key per pair, 10 × 9 ÷ 2 = 45. Public-key: each user needs only one key pair, so 10 × 2 = 20 keys. 10 counts only the public keys.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-194","question":"A piece of malware copies itself from computer to computer across a network on its own, without attaching to any file or needing a user to run a program. It is a:","options":["Virus","Trojan horse","Worm","Logic bomb"],"answer":2,"explanation":"A worm is self-replicating and standalone. A virus needs a host file and some user action to spread, and a Trojan disguises itself as useful software but does not replicate.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-195","question":"A bank publishes a value computed from a software installer so that customers can confirm the download has not been altered. The file itself stays readable by anyone. Which technique is this?","options":["Symmetric encryption","Steganography","Public-key encryption","Cryptographic hashing"],"answer":3,"explanation":"A hash (such as SHA-256) is a one-way fingerprint: any change to the file changes it, so it checks integrity. Encryption would hide the content, which is not the goal here.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-196","question":"On what basis does a simple packet-filtering firewall allow or block traffic?","options":["Source and destination IP addresses, ports and protocol in each packet header","The full content of e-mail attachments","The identity of the logged-in user on each PC","The reputation of the website's owner"],"answer":0,"explanation":"Packet filters look only at header fields such as IP addresses, port numbers and protocol. Inspecting content or user identity needs application-level or next-generation firewalls.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-197","question":"Which SQL command removes all the rows of a table AND the table's definition, so the table no longer exists?","options":["TRUNCATE TABLE","DELETE FROM","DROP TABLE","ALTER TABLE"],"answer":2,"explanation":"DROP removes the data and the structure. TRUNCATE and DELETE without WHERE empty the table but leave its definition in place.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-198","question":"An ORDERS table has CustomerID as a foreign key referring to CUSTOMER. A clerk tries to insert an order with CustomerID 9999, which does not exist in CUSTOMER. Which constraint is violated?","options":["Entity integrity","Domain integrity","Uniqueness of the primary key","Referential integrity"],"answer":3,"explanation":"Referential integrity requires every foreign-key value to match an existing primary key (or be NULL). Entity integrity concerns NULLs in the primary key of the same table.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-199","question":"Which SQL command is placed in the WRONG category?","options":["CREATE — Data Definition Language","GRANT — Data Control Language","UPDATE — Data Definition Language","SELECT — Data Query/Manipulation Language"],"answer":2,"explanation":"UPDATE changes the data inside a table, so it is DML. DDL commands (CREATE, ALTER, DROP, TRUNCATE) change the structure.","difficulty":"moderate","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-200","question":"Which of the following is NOT shared by the threads of one process?","options":["The program code","Global data","Open files","The stack"],"answer":3,"explanation":"Threads share their process's code, global data and open files, but each thread has its own stack and registers so it can run its own sequence of calls.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-201","question":"Print jobs from many users are first stored on disk and sent to a slow printer one by one, so the CPU can carry on with other work. This technique is called:","options":["Spooling","Paging","Thrashing","Swapping"],"answer":0,"explanation":"Spooling (Simultaneous Peripheral Operations On-Line) queues output for a slow device on disk. Paging and swapping move memory pages or processes, and thrashing is excessive paging.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-202","question":"Which sequence correctly describes how a TCP connection is set up by the three-way handshake?","options":["Server sends SYN first, client replies with SYN-ACK, server finishes with ACK","Client sends SYN, server replies with SYN-ACK, client finishes with ACK","Client sends SYN, server replies with FIN, client finishes with ACK","Client sends SYN and ACK together, server replies with SYN, client sends nothing more"],"answer":1,"explanation":"The side opening the connection (client) sends SYN, the server answers SYN-ACK (its own SYN plus an acknowledgement), and the client confirms with ACK. FIN is used to CLOSE a connection.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-203","question":"How does the Harvard architecture differ from the von Neumann architecture?","options":["It has no main memory, only registers","It keeps instructions and data in separate memories with separate buses","It stores programs on magnetic tape instead of RAM","It uses decimal rather than binary arithmetic"],"answer":1,"explanation":"Von Neumann machines share one memory and bus for code and data (causing the 'von Neumann bottleneck'); Harvard designs give instructions and data separate memories and paths so both can be fetched at once.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-204","question":"A processor runs at 2 GHz. An instruction that needs 4 clock cycles takes how long to execute?","options":["8 ns","0.5 ns","2 ns","0.125 ns"],"answer":2,"explanation":"At 2 GHz one cycle lasts 1 ÷ (2 × 10⁹) s = 0.5 ns, so 4 cycles take 2 ns. 8 ns wrongly multiplies the frequency by the cycles.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-205","question":"A 2 GHz processor needs on average 2.5 clock cycles per instruction (CPI). What is its speed in MIPS (million instructions per second)?","options":["5000 MIPS","800 MIPS","500 MIPS","1250 MIPS"],"answer":1,"explanation":"MIPS = clock rate ÷ (CPI × 10⁶) = 2000 MHz ÷ 2.5 = 800. Multiplying by the CPI instead of dividing gives the trap answer 5000.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-206","question":"A file system divides a 2 GB partition into blocks of 4 KB each (1 KB = 1024 bytes, 1 GB = 1024 MB). How many blocks are there?","options":["500,000","512,000","262,144","524,288"],"answer":3,"explanation":"2 GB = 2³¹ bytes and 4 KB = 2¹² bytes, so there are 2³¹ ÷ 2¹² = 2¹⁹ = 524,288 blocks. 500,000 comes from using powers of 10, which the question rules out.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-207","question":"An uncompressed image is 1920 × 1080 pixels with 24-bit colour. Taking 1 MB = 1024 × 1024 bytes, about how much storage does it need?","options":["About 47.5 MB","About 5.9 MB","About 2.0 MB","About 0.74 MB"],"answer":1,"explanation":"24 bits = 3 bytes per pixel: 1920 × 1080 × 3 = 6,220,800 bytes ≈ 5.93 MB. 47.5 MB forgets to convert bits to bytes, and 2.0 MB treats each pixel as 1 byte.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-208","question":"A branch needs a printer that can print the original and carbon copies of a multi-part form in a single pass. Which printer suits this?","options":["Laser printer","Dot-matrix printer","Inkjet printer","Thermal printer"],"answer":1,"explanation":"Only an impact printer such as dot-matrix strikes the paper hard enough to mark the copies underneath. Laser, inkjet and thermal printers are non-impact.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-209","question":"Match each reader with its typical use: 1. MICR 2. OMR 3. OCR 4. Barcode reader; a. converting a scanned printed page into editable text b. reading the code line at the bottom of a cheque c. checking shaded bubbles on an exam answer sheet d. reading a product's price tag at a billing counter","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d"],"answer":1,"explanation":"MICR reads magnetic-ink characters on cheques, OMR detects pencil marks in fixed positions, OCR recognises printed characters, and barcode readers read product codes.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-210","question":"Which port carries both high-definition digital video and multichannel audio over a single cable?","options":["VGA","PS/2","HDMI","DVI"],"answer":2,"explanation":"HDMI carries digital video and audio together. VGA is analogue video only, DVI is designed for video, and PS/2 connected keyboards and mice.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-211","question":"How many of these statements about CPU cache levels are correct? I. L1 cache is the smallest and fastest. II. In multi-core processors, L3 cache is usually shared by all the cores. III. L2 cache is larger than L1 but slower. IV. L3 cache is faster than L1 because it is bigger.","options":["Two","Three","Four","One"],"answer":1,"explanation":"I, II and III are correct. IV is wrong: bigger caches are slower, so speed falls from L1 to L2 to L3.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-212","question":"A disk controller copies a large block of data straight into RAM and interrupts the CPU only once, when the whole transfer is over. This technique is:","options":["Programmed I/O with polling","Interrupt-driven I/O, one interrupt per byte","Spooling","Direct Memory Access (DMA)"],"answer":3,"explanation":"With DMA the controller moves the data itself and signals the CPU only at the end, leaving the CPU free. In programmed and interrupt-driven I/O, the CPU handles every word.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-213","question":"A server with four CPUs runs four different processes truly at the same instant. This is best described as:","options":["Multiprogramming","Multiprocessing","Time-sharing on a single processor","Batch processing"],"answer":1,"explanation":"Multiprocessing uses more than one processor, so several processes run in parallel. Multiprogramming and time-sharing on one CPU only interleave processes; they never run at the same instant.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-214","question":"A user program needs to read a file from disk, which only the operating system may do. How does it get the OS to do this?","options":["By making a system call, which switches the CPU into kernel mode","By writing directly to the disk controller's registers","By calling the BIOS from user mode","By raising its own process priority"],"answer":0,"explanation":"Protected operations run in kernel mode; a user program requests them through a system call (trap). Direct hardware access from user mode is blocked by the OS.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-215","question":"Which pairing of memory-management scheme and the kind of fragmentation it suffers from is correct?","options":["Paging — external; segmentation — internal","Paging — none; segmentation — none","Paging — internal; segmentation — external","Paging — internal; segmentation — internal"],"answer":2,"explanation":"Paging uses fixed-size frames, so space is wasted inside the last page (internal). Segments vary in size, leaving scattered free holes between them (external).","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-216","question":"A process has 3 page frames, all empty at first, and refers to pages in the order 5, 0, 3, 5, 1, 0, 5, 2, 0, 1, 3. How many page faults occur under FIFO and under LRU replacement?","options":["FIFO 8, LRU 9","FIFO 9, LRU 9","FIFO 9, LRU 8","FIFO 6, LRU 8"],"answer":2,"explanation":"FIFO faults on 5, 0, 3, 1, 5, 2, 0, 1, 3 = 9. LRU keeps 5 and 0 longer because they were just used and faults on 5, 0, 3, 1, 0, 2, 1, 3 = 8. Six is the count for the optimal policy.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-217","question":"Arrange these networks from the smallest to the largest geographical coverage.","options":["LAN < PAN < MAN < WAN","PAN < LAN < WAN < MAN","PAN < MAN < LAN < WAN","PAN < LAN < MAN < WAN"],"answer":3,"explanation":"A PAN covers a person's surroundings (e.g. Bluetooth), a LAN a building, a MAN a city, and a WAN countries or the globe.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-218","question":"Under classful addressing, what is the default subnet mask of the host 150.10.5.7?","options":["255.0.0.0","255.255.0.0","255.255.255.0","255.255.255.255"],"answer":1,"explanation":"A first octet of 128–191 marks a class B address, whose default mask is 255.255.0.0. Class A (1–126) uses 255.0.0.0 and class C (192–223) uses 255.255.255.0.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-219","question":"A host has the address 192.168.10.77/26. What are the network address and the broadcast address of its subnet?","options":["192.168.10.0 and 192.168.10.255","192.168.10.77 and 192.168.10.127","192.168.10.64 and 192.168.10.128","192.168.10.64 and 192.168.10.127"],"answer":3,"explanation":"/26 makes blocks of 64 addresses: 0–63, 64–127, 128–191, 192–255. 77 falls in 64–127, so the network is .64 and the broadcast is .127. The .0/.255 pair ignores the subnet mask.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-220","question":"Which protocol transfers files securely by running over an SSH connection?","options":["SFTP","FTP","TFTP","SMTP"],"answer":0,"explanation":"SFTP (SSH File Transfer Protocol) uses SSH, by default on port 22, for encrypted transfer. FTP and TFTP send data in plain text, and SMTP sends e-mail.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-221","question":"A bank clerk logs in with a valid password but finds he can only view loan files, not approve them. The rule that limits what he may do after logging in is called:","options":["Authentication","Authorisation","Non-repudiation","Encryption"],"answer":1,"explanation":"Authentication proves WHO the user is (the password); authorisation decides WHAT that user may access or do. Non-repudiation stops someone denying an action they took.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-222","question":"An outsider without an access card walks into a bank's server room by closely following an employee through the secured door. This social-engineering trick is called:","options":["Shoulder surfing","Tailgating","Dumpster diving","Vishing"],"answer":1,"explanation":"Tailgating (piggybacking) means slipping into a restricted area behind someone authorised. Shoulder surfing is watching someone type, dumpster diving is searching discarded material, and vishing is voice phishing.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-223","question":"The word BANK is encrypted with a Caesar cipher that shifts each letter 3 places forward in the alphabet. What is the ciphertext?","options":["YXKH","EDQN","EDNQ","CBOL"],"answer":1,"explanation":"B→E, A→D, N→Q, K→N gives EDQN. YXKH shifts backwards, and CBOL shifts by only 1.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-224","question":"In SQL, which clause filters the groups produced by GROUP BY, for example to keep only branches whose total deposits exceed ₹1 crore?","options":["WHERE","ORDER BY","HAVING","DISTINCT"],"answer":2,"explanation":"WHERE filters individual rows BEFORE grouping and cannot use aggregates such as SUM(); HAVING filters the groups AFTER aggregation.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-225","question":"A table CUSTOMER has 6 rows; the Phone column is NULL in 2 of them. What do COUNT(*) and COUNT(Phone) return?","options":["6 and 6","4 and 4","6 and 4","4 and 6"],"answer":2,"explanation":"COUNT(*) counts every row, including those with NULLs, so it gives 6; COUNT(column) ignores NULL values, so COUNT(Phone) gives 4.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-226","question":"A bank allows joint accounts: one customer may hold several accounts, and one account may belong to several customers. What is the cardinality of the CUSTOMER–ACCOUNT relationship?","options":["One-to-one","One-to-many","Many-to-one","Many-to-many"],"answer":3,"explanation":"Both sides can have more than one partner, so it is many-to-many; in a relational design it needs a separate linking table such as DEPOSITOR(CustomerID, AccountNo).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-227","question":"In an ER model, the entity DEPENDENT (an employee's family member) cannot be uniquely identified without the EMPLOYEE it belongs to. What is DEPENDENT, and how is it drawn?","options":["A weak entity, drawn as a double rectangle","A strong entity, drawn as a double rectangle","A derived attribute, drawn as a dashed ellipse","A weak entity, drawn as a dashed ellipse"],"answer":0,"explanation":"An entity with no key of its own, identified through an owner entity, is a weak entity and is shown with a double rectangle (its identifying relationship as a double diamond). A dashed ellipse marks a derived attribute.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-228","question":"A database administrator moves a table to a faster disk and adds a new index. Neither the logical schema nor any application program has to change. This illustrates:","options":["Physical data independence","Logical data independence","Data redundancy","Referential integrity"],"answer":0,"explanation":"Changing how data is stored without affecting the logical (conceptual) schema is physical data independence. Logical data independence is changing the logical schema without affecting user views, which is harder to achieve.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-229","question":"Assertion (A): Creating an index on a column makes searches on that column faster. Reason (R): Every INSERT or UPDATE on the table must also update the index.","options":["A is true but R is false","Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but R describes the COST of an index (slower writes), not why searches get faster. Searches speed up because the index is a sorted structure (such as a B-tree) that avoids scanning the whole table.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-230","question":"How many of these statements are correct? I. A table can have only one primary key. II. A primary key column can never hold NULL. III. A table can have several UNIQUE constraints. IV. A primary key may consist of more than one column.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct: a table has one primary key, which is NOT NULL and unique, but it may be composite (several columns), and any number of other columns can carry UNIQUE constraints.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-231","question":"Two ATMs read a joint account's balance of ₹10,000 at the same moment. Each pays out ₹3,000 and writes back its own result. With no locking, what is this problem called and what balance is finally stored?","options":["A race condition (lost update); ₹7,000","A deadlock; ₹4,000","A race condition (lost update); ₹4,000","Starvation; ₹7,000"],"answer":0,"explanation":"Both ATMs compute 10,000 − 3,000 = 7,000, and the second write overwrites the first, so one withdrawal is lost and ₹7,000 is stored instead of ₹4,000. This lost update caused by uncontrolled concurrent access is a race condition.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-232","question":"A pen drive shows 20 GB free, yet copying a single 6 GB video file to it fails. Which is the most likely reason?","options":["The drive is formatted as FAT32, which cannot store a single file larger than 4 GB","The drive is formatted as NTFS, which cannot store a single file larger than 4 GB","USB ports cannot transfer files larger than 4 GB","Video files cannot be copied to removable media"],"answer":0,"explanation":"FAT32 limits each file to just under 4 GB, whatever the free space; reformatting to NTFS or exFAT removes the limit. NTFS supports very large files.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-233","question":"The controller that fires a car's airbag must respond within a few milliseconds every single time. What kind of operating system does it need?","options":["A batch operating system","A time-sharing operating system","A hard real-time operating system","A network operating system"],"answer":2,"explanation":"A hard real-time OS guarantees a response within a fixed deadline, where a late answer counts as a failure. Time-sharing systems aim for fair sharing, not guaranteed deadlines.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-234","question":"Which part of an operating system reads the commands a user types and passes them on to the kernel to be carried out?","options":["The BIOS","The compiler","The device driver","The shell"],"answer":3,"explanation":"The shell (command interpreter) is the interface between the user and the kernel. The kernel manages hardware and resources, but it does not read typed commands itself.","difficulty":"moderate","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-235","question":"A program can be downloaded and used at no cost for as long as you like, but its source code is kept secret and you may not modify it. It is:","options":["Freeware","Open-source software","Shareware","Copyleft software"],"answer":0,"explanation":"Freeware is free of charge but closed. Open-source and copyleft software make the source available to modify, and shareware is free only for a trial period or with limited features.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-236","question":"Which system program copies an executable file from disk into main memory and prepares it to start running?","options":["Assembler","Linker","Loader","Compiler"],"answer":2,"explanation":"The loader places the program in memory (adjusting addresses if needed) and hands control to it. The linker runs earlier, joining object files into the executable.","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-237","question":"Assertion (A): The decimal fraction 0.1 cannot be stored exactly in binary floating point. Reason (R): 1/10 has the factor 5 in its denominator, so its binary expansion repeats forever.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Only fractions whose denominator is a power of 2 terminate in binary. 0.1 = 1/(2 × 5) becomes 0.000110011… repeating, so it is rounded when stored; R gives exactly this reason.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-238","question":"What is (1010.11)₂ + (3.25)₁₀, expressed in binary?","options":["(1101.11)₂","(1110.11)₂","(1101.01)₂","(1110)₂"],"answer":3,"explanation":"(1010.11)₂ = 8 + 2 + 0.5 + 0.25 = 10.75, and 10.75 + 3.25 = 14 = (1110)₂. The fractional parts add up to exactly 1, so no fraction is left.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-239","question":"If (121)_b = (49)₁₀, what is the base b?","options":["6","7","8","5"],"answer":0,"explanation":"(121)_b = b² + 2b + 1 = (b + 1)² = 49, so b + 1 = 7 and b = 6. Check: 36 + 12 + 1 = 49. Base 7 would give 64.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-240","question":"A 16-bit register holds (FFFF)₁₆, read as a two's-complement signed integer. What value does it hold?","options":["65535","−32768","−1","−32767"],"answer":2,"explanation":"All 16 bits are 1; inverting gives 0 and adding 1 gives 1, so the value is −1. 65535 is the unsigned reading, and −32768 is the pattern 8000.","difficulty":"hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-241","question":"Two 8-bit two's-complement numbers, 01100100 (100) and 00110010 (50), are added. What does the 8-bit result hold?","options":["10010110, which reads as −106: an overflow has occurred","10010110, which reads as 150: no overflow","01111111: the result is held at the maximum, 127","00010110 with a carry out of 1, which reads as 22"],"answer":0,"explanation":"The sum 150 exceeds the 8-bit signed maximum of 127. The bits 10010110 are produced, which in two's complement mean 150 − 256 = −106; adding two positives and getting a negative is the sign of overflow.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-242","question":"In a half adder, which gates produce the Sum and the Carry outputs?","options":["Sum from AND, Carry from XOR","Sum from XOR, Carry from AND","Sum from OR, Carry from AND","Sum from XNOR, Carry from OR"],"answer":1,"explanation":"Adding two bits gives Sum = 1 when exactly one input is 1 (XOR) and Carry = 1 only when both are 1 (AND).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-243","question":"For how many of the 8 possible combinations of the inputs A, B and C does the circuit (A NAND B) NOR C output 1?","options":["7","3","5","1"],"answer":3,"explanation":"A NOR gate outputs 1 only when both its inputs are 0: A NAND B = 0 needs A = B = 1, and C must be 0. Only the combination A = 1, B = 1, C = 0 works.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-244","question":"Twenty-four PCs are connected one to a port on a 24-port switch with no VLANs configured. How many collision domains and how many broadcast domains does this network have?","options":["24 collision domains, 1 broadcast domain","1 collision domain, 1 broadcast domain","1 collision domain, 24 broadcast domains","24 collision domains, 24 broadcast domains"],"answer":0,"explanation":"Each switch port is its own collision domain, but a switch forwards broadcasts to every port, so there is one broadcast domain; only a router (or VLANs) splits broadcast domains. With a hub, there would be 1 collision domain.","difficulty":"very-hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-245","question":"Bank staff working from home need to reach the office network over the public internet, with all traffic encrypted as if they were inside the office. Which technology provides this?","options":["Network Address Translation (NAT)","A proxy server","A virtual private network (VPN)","A demilitarised zone (DMZ)"],"answer":2,"explanation":"A VPN builds an encrypted tunnel across the public internet into the private network. NAT only maps private to public addresses, and a DMZ is a separate zone for public-facing servers.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-246","question":"A bank rents virtual machines, storage and network capacity from a cloud provider, then installs and manages its own operating system and applications on them. Which cloud service model is this?","options":["Software as a Service (SaaS)","Infrastructure as a Service (IaaS)","Platform as a Service (PaaS)","Function as a Service (FaaS)"],"answer":1,"explanation":"In IaaS the provider supplies raw computing infrastructure and the customer manages the OS upwards. In PaaS the provider also manages the OS and runtime, and in SaaS the whole application.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-247","question":"Match the IEEE standard with the technology: 1. IEEE 802.3 2. IEEE 802.11 3. IEEE 802.15; a. Wireless LAN (Wi-Fi) b. Wired Ethernet c. Wireless personal area network such as Bluetooth","options":["1-a, 2-b, 3-c","1-c, 2-a, 3-b","1-b, 2-c, 3-a","1-b, 2-a, 3-c"],"answer":3,"explanation":"802.3 is Ethernet, 802.11 is Wi-Fi and 802.15 covers wireless personal area networks, including Bluetooth (802.15.1).","difficulty":"hard","source":"IBPS SO IT · IBPS PO Mains"},
  {"id":"comp-awareness-248","question":"A hypervisor installed directly on a server's hardware, with no host operating system beneath it, is called a:","options":["Type 1 (bare-metal) hypervisor","Type 2 (hosted) hypervisor","Container engine","Boot loader"],"answer":0,"explanation":"Type 1 hypervisors run straight on the hardware; Type 2 hypervisors run as an application on top of an ordinary host OS. Containers share the host kernel instead of virtualising hardware.","difficulty":"very-hard","source":"IBPS SO IT · SBI PO"},
  {"id":"comp-awareness-249","question":"The processing speed of supercomputers is usually compared using which unit?","options":["MIPS","Clock speed in GHz","FLOPS","Revolutions per minute (rpm)"],"answer":2,"explanation":"Supercomputers do heavy scientific calculations, so they are rated in floating-point operations per second (FLOPS), e.g. petaFLOPS. MIPS counts general instructions, and GHz alone ignores how much work each cycle does.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
  {"id":"comp-awareness-250","question":"Which pair consists ONLY of lossless compression formats, from which the original data can be rebuilt exactly?","options":["JPEG and MP3","PNG and JPEG","ZIP and MP3","ZIP and PNG"],"answer":3,"explanation":"ZIP archives and PNG images are lossless. JPEG and MP3 are lossy: they throw away detail the eye or ear is unlikely to notice, so the original cannot be restored exactly.","difficulty":"hard","source":"IBPS PO Mains · SBI PO"},
];

